begin;
select pg_advisory_xact_lock(hashtext('prepyard-patterns-v1'));
-- Remove memberships only. Canonical questions and student records survive.
delete from public.pattern_collections where slug in ('striver-sde','striver-a2z','neetcode-150','blind-75','kushal-essential-patterns','prepyard-foundations','prepyard-sequence-strategies','prepyard-structure-traversal','prepyard-search-and-dp');
delete from public.question_patterns where mapping_source in ('prepyard-patterns-v1','prepyard-collections-v1');
alter policy pattern_collections_read on public.pattern_collections using (private.student_id() is not null and slug in ('interview-launchpad','dsa-deep-dive','interview-hotlist'));
create or replace view public.topic_frequency_questions with (security_invoker=true) as
with per_company as (
 select question_id,company_id,max(frequency) frequency
 from public.company_question_observations
 where time_window='all' and frequency_kind='percent' and frequency>0
 group by question_id,company_id
), scored as (
 select question_id,max(frequency) reported_frequency,count(*)::int company_count
 from per_company group by question_id
), ranked as (
 select q.id question_id,qt.topic_id,s.reported_frequency,s.company_count,
 row_number() over(partition by qt.topic_id order by s.reported_frequency desc,s.company_count desc,lower(q.title),q.canonical_url,q.id)::int position
 from scored s join public.questions q on q.id=s.question_id and q.is_listed
 join public.question_dsa_topics qt on qt.question_id=q.id
 where private.student_id() is not null
)
select * from ranked where position<=20;
revoke all on public.topic_frequency_questions from public,anon,authenticated;
grant select on public.topic_frequency_questions to authenticated,service_role;
insert into public.pattern_collections(slug,name) values('interview-hotlist','Interview Hotlist') on conflict(slug) do update set name=excluded.name;

-- Generated from the attributed practice manifest. Run as administrator in SQL
-- Editor after existing migrations. All changes roll back on any error.
select pg_advisory_xact_lock(hashtext('prepyard-patterns-v1'));
do $prepyard$
declare
 sheet jsonb; item jsonb; entry jsonb; pair jsonb; pattern_name text; tag jsonb;
 v_platform_id uuid; v_leetcode_id uuid; v_tag_id uuid; v_topic_id uuid; v_pattern_id uuid; v_question_id uuid; v_collection_id uuid;
 existing record; v_position integer; student_counts bigint[];
begin
 select array[(select count(*) from public.user_question_state),(select count(*) from public.notes),(select count(*) from public.practice_events)] into student_counts;
 insert into public.platforms(slug,name,base_url) values('leetcode','LeetCode','https://leetcode.com'),('geeksforgeeks','GeeksforGeeks','https://www.geeksforgeeks.org'),('spoj','SPOJ','https://www.spoj.com') on conflict(slug) do update set name=excluded.name;
 select id into v_leetcode_id from public.platforms where slug='leetcode';
 v_position:=0;
 for pair in select value from jsonb_array_elements('[["arrays","Arrays"],["strings","Strings"],["hash-tables","Hash Tables"],["linked-lists","Linked Lists"],["stacks","Stacks"],["queues","Queues"],["matrices","Matrices"],["trees","Trees"],["binary-search-trees","Binary Search Trees"],["heaps","Heaps"],["graphs","Graphs"],["tries","Tries"],["dynamic-programming","Dynamic Programming"],["recursion","Recursion"],["sorting-and-searching","Sorting and Searching"],["bit-manipulation","Bit Manipulation"],["mathematics","Mathematics"],["data-structures","Data Structures"],["algorithms","Algorithms"]]'::jsonb) loop
   insert into public.dsa_topics(slug,name,position) values(pair->>0,pair->>1,v_position) on conflict(slug) do update set name=excluded.name,position=excluded.position;
   v_position:=v_position+1;
 end loop;
 for pair in select value from jsonb_array_elements('[["prefix-sum","Prefix Sum"],["two-pointers","Two Pointers"],["sliding-window","Sliding Window"],["monotonic-stack","Monotonic Stack"],["monotonic-queue","Monotonic Queue"],["binary-search","Binary Search"],["breadth-first-search-bfs","Breadth First Search (BFS)"],["depth-first-search-dfs","Depth First Search (DFS)"],["backtracking","Backtracking"],["topological-sort","Topological Sort"],["union-find","Union-Find"],["greedy","Greedy"],["divide-and-conquer","Divide and Conquer"],["memoization","Memoization"],["bitmask","Bitmask"],["shortest-path","Shortest Path"],["minimum-spanning-tree","Minimum Spanning Tree"]]'::jsonb) loop
   insert into public.patterns(slug,name) values(pair->>0,pair->>1) on conflict(slug) do update set name=excluded.name;
 end loop;
 delete from public.question_patterns where mapping_source in ('prepyard-editorial-v1','prepyard-topic-tags-v2');
 for sheet in select value from jsonb_array_elements('[{"slug":"interview-launchpad","name":"Interview Launchpad","description":"A focused set of essential interview exercises.","kind":"static","expectedCount":66,"referenceUrl":"https://codolio.com/question-tracker/sheet/manasi-deshmane-dsa-sheet?category=all","questions":[{"platform":"leetcode","externalId":"1","title":"Two Sum","url":"https://leetcode.com/problems/two-sum/","difficulty":"easy","topic":"arrays","patterns":[],"topics":[{"slug":"array","name":"Array"},{"slug":"hash-table","name":"Hash Table"}]},{"platform":"leetcode","externalId":"53","title":"Maximum Subarray","url":"https://leetcode.com/problems/maximum-subarray/","difficulty":"medium","topic":"dynamic-programming","patterns":["Divide and Conquer"],"topics":[{"slug":"array","name":"Array"},{"slug":"divide-and-conquer","name":"Divide and Conquer"},{"slug":"dynamic-programming","name":"Dynamic Programming"}]},{"platform":"leetcode","externalId":"56","title":"Merge Intervals","url":"https://leetcode.com/problems/merge-intervals/","difficulty":"medium","topic":"arrays","patterns":[],"topics":[{"slug":"array","name":"Array"},{"slug":"quicksort","name":"Quicksort"},{"slug":"sorting","name":"Sorting"}]},{"platform":"leetcode","externalId":"31","title":"Next Permutation","url":"https://leetcode.com/problems/next-permutation/","difficulty":"medium","topic":"arrays","patterns":["Two Pointers"],"topics":[{"slug":"array","name":"Array"},{"slug":"two-pointers","name":"Two Pointers"}]},{"platform":"leetcode","externalId":"121","title":"Best Time to Buy and Sell Stock","url":"https://leetcode.com/problems/best-time-to-buy-and-sell-stock/","difficulty":"easy","topic":"dynamic-programming","patterns":[],"topics":[{"slug":"array","name":"Array"},{"slug":"dynamic-programming","name":"Dynamic Programming"}]},{"platform":"leetcode","externalId":"238","title":"Product of Array Except Self","url":"https://leetcode.com/problems/product-of-array-except-self/","difficulty":"medium","topic":"arrays","patterns":["Prefix Sum"],"topics":[{"slug":"array","name":"Array"},{"slug":"prefix-sum","name":"Prefix Sum"}]},{"platform":"leetcode","externalId":"287","title":"Find the Duplicate Number","url":"https://leetcode.com/problems/find-the-duplicate-number/","difficulty":"medium","topic":"arrays","patterns":["Two Pointers","Binary Search"],"topics":[{"slug":"array","name":"Array"},{"slug":"binary-search","name":"Binary Search"},{"slug":"bit-manipulation","name":"Bit Manipulation"},{"slug":"floyds-cycle-finding-algorithm","name":"Floyd''s Cycle Finding Algorithm"},{"slug":"pigeonhole-principle","name":"Pigeonhole Principle"},{"slug":"two-pointers","name":"Two Pointers"}]},{"platform":"leetcode","externalId":"560","title":"Subarray Sum Equals K","url":"https://leetcode.com/problems/subarray-sum-equals-k/","difficulty":"medium","topic":"arrays","patterns":["Prefix Sum"],"topics":[{"slug":"array","name":"Array"},{"slug":"hash-table","name":"Hash Table"},{"slug":"prefix-sum","name":"Prefix Sum"}]},{"platform":"leetcode","externalId":"42","title":"Trapping Rain Water","url":"https://leetcode.com/problems/trapping-rain-water/","difficulty":"hard","topic":"dynamic-programming","patterns":["Two Pointers","Monotonic Stack"],"topics":[{"slug":"array","name":"Array"},{"slug":"dynamic-programming","name":"Dynamic Programming"},{"slug":"monotonic-stack","name":"Monotonic Stack"},{"slug":"stack","name":"Stack"},{"slug":"two-pointers","name":"Two Pointers"}]},{"platform":"leetcode","externalId":"15","title":"3Sum","url":"https://leetcode.com/problems/3sum/","difficulty":"medium","topic":"arrays","patterns":["Two Pointers"],"topics":[{"slug":"array","name":"Array"},{"slug":"sorting","name":"Sorting"},{"slug":"two-pointers","name":"Two Pointers"}]},{"platform":"leetcode","externalId":"242","title":"Valid Anagram","url":"https://leetcode.com/problems/valid-anagram/","difficulty":"easy","topic":"strings","patterns":[],"topics":[{"slug":"hash-table","name":"Hash Ta